// Minimal placeholder for org.eclipse.ui.ISharedImages
interface ISharedImages {
    String IMG_DEF_MISSING = "IMG_DEF_MISSING";
    static ISharedImages get() { return new ISharedImages() {}; }
    Image getImage(String key);
}

public class AfterExample {
    public Image getMissingImage() {
        // This retrieves a shared, managed image, no manual disposal needed.
        return ISharedImages.get().getImage(ISharedImages.IMG_DEF_MISSING);
    }

    public void processImage() {
        Image img = ISharedImages.get().getImage(ISharedImages.IMG_DEF_MISSING);
        // ... use img ...
        // No img.dispose() is needed as the image is shared and managed by the workbench.
    }
}

